 $('selectionCount').textContent=multi.size>1?multi.size+' objekt markerade · flytta, vrid eller gruppera':'Shift-klick väljer flera objekt.';updateTapeUI();updateCompare();$('doorAngle').value=api.door?.target||0;$('doorAngleValue').textContent=Math.round(api.door?.target||0)+'°';$('doorDirection').value=String(api.door?.direction||1);
