 function thumbnail(canvas,geometry){const c=canvas.getContext('2d');canvas.width=248;canvas.height=156;const eye=[.58,.56,.59],len=Math.hypot(...eye),f=eye.map(v=>v/len),r=[f[2],0,-f[0]],rl=Math.hypot(...r);for(let i=0;i<3;i++)r[i]/=rl;const u=[f[1]*r[2]-f[2]*r[1],f[2]*r[0]-f[0]*r[2],f[0]*r[1]-f[1]*r[0]],dot=(a,b)=>a.reduce((s,v,i)=>s+v*b[i],0),faces=[];let xs=[],ys=[];
 for(let g of geometry)for(let k=0;k<g.p.length;k+=9){let ps=[...g.p.slice(k,k+9)],verts=[ps.slice(0,3),ps.slice(3,6),ps.slice(6,9)],normal=[...g.n.slice(k,k+3)];if(dot(normal,f)<-.01)continue;let points=verts.map(v=>[dot(v,r),-dot(v,u)]);points.forEach(p=>{xs.push(p[0]);ys.push(p[1])});faces.push({pts:points,z:verts.reduce((s,v)=>s+dot(v,f),0)/3,n:normal,color:C.MATS[g.mat]});}
 const mnx=Math.min(...xs),mxx=Math.max(...xs),mny=Math.min(...ys),mxy=Math.max(...ys),scale=Math.min(191/(mxx-mnx),122/(mxy-mny)),cx=(mnx+mxx)/2,cy=(mny+mxy)/2;c.clearRect(0,0,248,156);c.fillStyle='#173e2010';c.beginPath();c.ellipse(124,138,67,8,0,0,Math.PI*2);c.fill();faces.sort((a,b)=>a.z-b.z);for(let f of faces){let lit=.78+.23*Math.max(0,dot(f.n,[-.4,.85,.35]));c.fillStyle='rgb('+f.color.slice(0,3).map(v=>Math.min(255,Math.round(v*lit*255))).join(',')+')';c.beginPath();f.pts.forEach((p,i)=>c[i?'lineTo':'moveTo'](124+(p[0]-cx)*scale,76+(p[1]-cy)*scale));c.closePath();c.fill();c.strokeStyle=c.fillStyle;c.lineWidth=.6;c.stroke();}}
 function uploadGeometry(geometry){const parts=[];for(let g of geometry){const vao=gl.createVertexArray();gl.bindVertexArray(vao);const buffers=[];for(const [i,a,n]of[[0,g.p,3],[1,g.n,3],[2,g.uv,2]]){const b=gl.createBuffer();buffers.push(b);gl.bindBuffer(gl.ARRAY_BUFFER,b);gl.bufferData(gl.ARRAY_BUFFER,a,gl.STATIC_DRAW);gl.enableVertexAttribArray(i);gl.vertexAttribPointer(i,n,gl.FLOAT,false,0,0);}parts.push({vao,count:g.p.length/3,mat:g.mat,buffers});}return{geometry,parts};}
