 function tapeResource(tape){const key=JSON.stringify(tape),old=tapeCache.get(tape.id);if(old?.key===key)return old;const res=uploadGeometry(C.buildTapeGeometry(tape));res.key=key;if(old)dispose(old);tapeCache.set(tape.id,res);return res;}
