 function prepareRender(){let visible=showFurniture?objects.filter(o=>(o.y||0)<.3&&!o.mount):[],data=new Float32Array(C.LIMIT*4),rot=new Float32Array(C.LIMIT*2);visible.forEach((o,i)=>{data.set([o.x,o.z,o.w/2,o.d/2],i*4);rot.set([Math.cos(o.rot*Math.PI/180),Math.sin(o.rot*Math.PI/180)],i*2)});gl.uniform1i(U.shadowCount,visible.length);gl.uniform4fv(U.shadows,data);gl.uniform2fv(U.shadowRot,rot);}
